<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\Accessor;

use Civi\Lughauth\Features\Document\TemplateSnippet\Domain\ValueObject\TemplateSnippetCodeVO;

trait TemplateSnippetCodeAccessor
{
    private TemplateSnippetCodeVO $_code;
    public function getCode(): string
    {
        return $this->_code->value();
    }
    public function code(): TemplateSnippetCodeVO
    {
        return $this->_code;
    }
    public function isCodeChanged(?self $original = null): bool
    {
        return !$this->_code->equals($original?->_code);
    }
    public function withCode(TemplateSnippetCodeVO|string $code): self
    {
        $copy = clone $this;
        $copy->_code = TemplateSnippetCodeVO::from($code);
        return $copy;
    }
}
